<?php
require_once __DIR__ . '/session.php';
require_once __DIR__ . '/../database/connection.php';
function inbox_h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$messages = [];
$quotes = [];
$loadError = false;
try {
    $db = app_db();
    $messages = $db->query('SELECT id,name,email,subject,message,status,created_at FROM contact_messages ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
    $quotes = $db->query('SELECT id,first_name,last_name,email,contact_number,pickup_city,pickup_state,delivery_city,delivery_state,shipment_type,pickup_type,content,status,created_at FROM quote_requests ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
} catch (Throwable $exception) {
    error_log('Admin inbox query failed: ' . get_class($exception));
    $loadError = true;
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact & quotes · NEXTGEN Logistics</title><link rel="stylesheet" href="../css/bootstrap.css"><link rel="stylesheet" href="assets/admin.css"><style>.inbox-grid{display:grid;gap:22px}.inbox-item{border:1px solid #e5ebf4;border-radius:12px;padding:16px;background:#fff;margin:12px 0}.inbox-item h3{font-size:16px;margin:0 0 6px}.inbox-meta{font-size:12px;color:#77859a;margin-bottom:10px}.inbox-message{white-space:pre-wrap;overflow-wrap:anywhere;color:#35445b}.inbox-empty{padding:22px;color:#77859a;text-align:center}</style></head><body class="admin-app"><header class="admin-topbar"><a class="admin-brand" href="dashboard.php"><span class="admin-brand-mark">N</span><span>NEXTGEN <span style="font-weight:500;color:#748198">Logistics</span></span></a><div class="admin-top-right"><a class="admin-btn admin-btn-light" href="dashboard.php">Back to dashboard</a><a class="admin-icon-btn" href="logout.php" aria-label="Sign out" title="Sign out">↗</a></div></header><main class="admin-main" style="max-width:1100px;margin:0 auto"><div class="admin-heading"><div><p class="admin-eyebrow">Customer communication</p><h1>Contact & quote requests</h1><p class="admin-subtitle">Recent messages and quote submissions stored in the SQLite database.</p></div></div><?php if($loadError): ?><div class="admin-alert" role="alert">Inbox data is temporarily unavailable.</div><?php else: ?><div class="inbox-grid"><section class="admin-panel" style="padding:22px"><h2>Contact messages (latest 100)</h2><?php if(!$messages): ?><div class="inbox-empty">No contact messages have been submitted.</div><?php else: foreach($messages as $message): ?><article class="inbox-item"><h3><?=inbox_h($message['subject'] !== '' ? $message['subject'] : 'Contact message')?></h3><div class="inbox-meta"><?=inbox_h($message['name'])?> · <?=inbox_h($message['email'])?> · <?=inbox_h($message['created_at'])?> · <?=inbox_h($message['status'])?></div><div class="inbox-message"><?=inbox_h($message['message'])?></div></article><?php endforeach; endif; ?></section><section class="admin-panel" style="padding:22px"><h2>Quote requests (latest 100)</h2><?php if(!$quotes): ?><div class="inbox-empty">No quote requests have been submitted.</div><?php else: foreach($quotes as $quote): ?><article class="inbox-item"><h3><?=inbox_h(trim($quote['first_name'].' '.$quote['last_name']))?> — <?=inbox_h($quote['shipment_type'])?></h3><div class="inbox-meta"><?=inbox_h($quote['email'])?> · <?=inbox_h($quote['contact_number'])?> · <?=inbox_h($quote['created_at'])?> · <?=inbox_h($quote['status'])?></div><p><strong>Route:</strong> <?=inbox_h($quote['pickup_city'].', '.$quote['pickup_state'])?> → <?=inbox_h($quote['delivery_city'].', '.$quote['delivery_state'])?></p><p><strong>Pickup type:</strong> <?=inbox_h($quote['pickup_type'])?></p><p><strong>Contents:</strong> <?=inbox_h($quote['content'])?></p></article><?php endforeach; endif; ?></section></div><?php endif; ?></main></body></html>
